(function(){for(var path=location.pathname.replace(/\/+$/,"")||"/",APP=["/dashboard","/squad-analysis"],inApp=!1,i=0;i<APP.length;i++)if(path===APP[i]||path.indexOf(APP[i]+"/")===0){inApp=!0;break}if(inApp){var OPEN=["/dashboard/login","/dashboard/scouts-desk","/dashboard/news"];if(OPEN.indexOf(path)===-1){var KNOWN=["/dashboard","/dashboard/my-team","/dashboard/squad","/dashboard/players","/dashboard/teams","/dashboard/rivals","/dashboard/premium"];if(path.indexOf("/dashboard")===0&&OPEN.indexOf(path)===-1&&KNOWN.indexOf(path)===-1){location.replace("/404.html");return}var id=null;try{id=localStorage.getItem("fpl_team_id")}catch{}if(!id){var next=path+location.search+location.hash;location.replace("/dashboard/login?next="+encodeURIComponent(next))}}}})();
